CREATE TABLE `candidate_assets` (
	`id` text PRIMARY KEY NOT NULL,
	`candidate_id` text NOT NULL,
	`item_order` integer NOT NULL,
	`asset_type` text NOT NULL,
	`description` text NOT NULL,
	`value_cents` integer NOT NULL,
	`updated_at` text NOT NULL,
	FOREIGN KEY (`candidate_id`) REFERENCES `candidates`(`source_record_id`) ON UPDATE no action ON DELETE cascade
);
--> statement-breakpoint
CREATE INDEX `candidate_assets_candidate_idx` ON `candidate_assets` (`candidate_id`);--> statement-breakpoint
CREATE UNIQUE INDEX `candidate_assets_candidate_order_idx` ON `candidate_assets` (`candidate_id`,`item_order`);--> statement-breakpoint
CREATE TABLE `candidate_details` (
	`candidate_id` text PRIMARY KEY NOT NULL,
	`age_at_inauguration` integer,
	`nationality` text NOT NULL,
	`birth_city` text NOT NULL,
	`is_reelection` text NOT NULL,
	`declares_assets` text NOT NULL,
	`campaign_expense_limit_cents` integer,
	`registration_process_number` text NOT NULL,
	`judgment_status` text NOT NULL,
	`accepted_at` text,
	`asset_count` integer DEFAULT 0 NOT NULL,
	`asset_total_cents` integer DEFAULT 0 NOT NULL,
	`social_count` integer DEFAULT 0 NOT NULL,
	FOREIGN KEY (`candidate_id`) REFERENCES `candidates`(`source_record_id`) ON UPDATE no action ON DELETE cascade
);
--> statement-breakpoint
CREATE INDEX `candidate_details_judgment_idx` ON `candidate_details` (`judgment_status`);--> statement-breakpoint
CREATE TABLE `candidate_social_links` (
	`id` text PRIMARY KEY NOT NULL,
	`candidate_id` text NOT NULL,
	`item_order` integer NOT NULL,
	`platform` text NOT NULL,
	`url` text NOT NULL,
	FOREIGN KEY (`candidate_id`) REFERENCES `candidates`(`source_record_id`) ON UPDATE no action ON DELETE cascade
);
--> statement-breakpoint
CREATE INDEX `candidate_social_candidate_idx` ON `candidate_social_links` (`candidate_id`);--> statement-breakpoint
CREATE UNIQUE INDEX `candidate_social_candidate_order_idx` ON `candidate_social_links` (`candidate_id`,`item_order`);
